mapper.select:
SELECT svc.service_name AS serviceName, cc.course_class_name AS courseClassName, st.student_no AS studentNo, st.student_name AS studentName, cs.session_date, date_format(cs.start_time, '%H:%i') AS startTime, date_format(cs.end_time, '%H:%i') AS endTime, st.term_id, st.class_id AS classId, st.grade_id AS gradeId, cs.teacher_id AS teacherId, cs.id AS sessionId, t.teacher_name AS teacherName, fb.id AS feedbackId, fb.update_time AS checkInDate, CASE WHEN fb.id IS NOT NULL THEN 1 ELSE 0 END AS isCheckIn FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_term te ON te.id = svc.term_id AND te.is_valid = 1 INNER JOIN t_as_enrollment en ON en.course_class_id = cc.id AND en.is_valid = 1 AND en.enroll_status in (1,3) INNER JOIN t_as_student st ON en.student_id = st.id AND st.is_valid = 1 LEFT JOIN t_as_teacher t ON cs.teacher_id = t.id AND t.is_valid = 1 LEFT JOIN t_as_course_stu_feedback fb ON fb.session_id = cs.id AND fb.student_id = st.id AND fb.is_valid = 1
cs.is_valid = 1 AND cs.session_status = 2 and st.register_status = 1 AND st.school_id = #{query.schoolId}
AND cc.id = #{query.courseClassId}
AND st.class_id = #{query.classId}
AND (st.student_name LIKE CONCAT('%', #{query.studentKeyword}, '%') OR st.student_no LIKE CONCAT('%', #{query.studentKeyword}, '%'))
AND DATE(cs.session_date) BETWEEN DATE(#{query.sessionStartDate}) AND DATE(#{query.sessionEndDate})
AND t.teacher_name = #{query.teacherName}
AND svc.term_id = #{query.termId}
GROUP BY cs.id,st.id ORDER BY cs.session_date DESC,cc.id desc, st.student_no ASC

SELECT school_id AS schoolId, COUNT(*) AS cnt FROM t_as_student WHERE is_valid = 1 AND register_status = 1 AND school_roll_status = 1 AND school_id IN
#{id}
GROUP BY school_id

SELECT DISTINCT stu.id AS studentId, gs.id AS parentId, gs.guardian_user_id AS parentUserId FROM t_as_student stu INNER JOIN t_as_guardian_student gs on gs.student_identity_id = stu.student_identity_id and gs.is_valid = 1 and bind_status = 1 WHERE stu.is_valid = 1 and stu.register_status = 1 and gs.guardian_user_id is not NULL AND stu.school_id = #{query.schoolId}
AND stu.term_id = #{query.termId}
AND stu.grade_id in
#{item}
AND stu.class_id in
#{item}

SELECT t2.id, t2.student_identity_id AS studentIdentityId, t1.school_id AS schoolId, t1.student_name AS studentName, t1.student_no AS studentNo, t1.id_card AS idCard, t1.gender, t1.enrollment_year, t2.term_id AS termId, t2.grade_id AS gradeId, t2.class_id AS classId, t2.school_roll_status AS schoolRollStatus, t2.register_status AS registerStatus, t1.avatar_file_id AS avatarFileId, t2.update_time AS updateTime, te.term_name AS termName, t2.graduation_year AS graduationYear FROM t_as_student_identity t1 LEFT JOIN ( SELECT s.* FROM t_as_student s INNER JOIN ( SELECT s1.student_identity_id, MAX(s1.create_time) AS max_time FROM t_as_student s1 GROUP BY s1.student_identity_id ) t_max ON s.student_identity_id = t_max.student_identity_id AND s.create_time = t_max.max_time ) t2 ON t1.id = t2.student_identity_id INNER JOIN t_educl_term te ON te.id = t2.term_id AND te.is_valid = 1 WHERE t1.is_valid = 1
AND t1.school_id = #{query.schoolId}
AND t1.student_name LIKE CONCAT('%', #{query.studentName}, '%')
AND t1.student_no LIKE CONCAT('%', #{query.studentNo}, '%')
AND t2.grade_id = #{query.gradeId}
AND t2.class_id = #{query.classId}
AND (t2.term_id = #{query.termId} OR t2.school_roll_status = 2)
AND t2.school_roll_status = #{query.schoolRollStatus}
AND t2.register_status = #{query.registerStatus}
ORDER BY t2.class_id desc, t1.student_no ASC

