SELECT s.*, g.grade_name AS gradeName, c.class_name AS className
FROM t_as_student s
INNER JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1
INNER JOIN t_educl_class c ON s.class_id = c.id AND c.is_valid = 1
WHERE  s.school_id = #{schoolId}
AND s.term_id = #{termId}
AND s.register_status = 1
and s.is_valid = 1

    AND s.class_id IN

        #{cid}



    AND s.grade_id IN

        #{gid}



    AND (s.student_no LIKE CONCAT('%', #{keyword}, '%')
    OR s.student_name LIKE CONCAT('%', #{keyword}, '%'))

AND s.grade_id = #{gradeId}
AND s.class_id = #{classId}
